namespace RayBork.Internal;

/// <summary>
/// The GLSL identifiers generated by the bake prologue. They are part of the shader ABI contract:
/// user GLSL refers to them and must not redeclare them.
/// </summary>
/// <remarks>
/// The names are generated into every shader module; changing one is an ABI break that requires the
/// bake, the runtime pipeline layout, and the API reference to change together.
/// </remarks>
internal static class ShaderAbiNames {
    /// <summary>The frame uniform block struct type: <c>RayBorkFrame</c>.</summary>
    internal const string FRAME_TYPE = "RayBorkFrame";

    /// <summary>The frame uniform block type: <c>RayBorkFrameBlock</c>.</summary>
    internal const string FRAME_BLOCK = "RayBorkFrameBlock";

    /// <summary>The frame uniform block instance: <c>rbFrameBlock</c>.</summary>
    internal const string FRAME_BLOCK_INSTANCE = "rbFrameBlock";

    /// <summary>The frame block member name: <c>frame</c>.</summary>
    internal const string FRAME_FIELD = "frame";

    /// <summary>The frame accessor macro: <c>rbFrame</c>.</summary>
    internal const string FRAME_ACCESSOR = "rbFrame";

    /// <summary>The bindless sampler array: <c>RayBorkTextures</c>.</summary>
    internal const string TEXTURES = "RayBorkTextures";

    /// <summary>
    /// The fixed number of combined image samplers in <see cref="TEXTURES"/>: 2048. The prologue
    /// declares <c>RayBorkTextures[2048]</c> and the descriptor set layout must declare the same
    /// descriptor count.
    /// </summary>
    internal const uint TEXTURE_CAPACITY = 2048;

    /// <summary>The per-instance record struct type: <c>RayBorkInstance</c>.</summary>
    internal const string INSTANCE_TYPE = "RayBorkInstance";

    /// <summary>The instance storage buffer type: <c>RayBorkInstanceBuffer</c>.</summary>
    internal const string INSTANCE_BUFFER = "RayBorkInstanceBuffer";

    /// <summary>The instance storage buffer instance: <c>RayBorkInstances</c>.</summary>
    internal const string INSTANCES = "RayBorkInstances";

    /// <summary>The instance record array member name: <c>instances</c>.</summary>
    internal const string INSTANCES_FIELD = "instances";

    /// <summary>The stage-specific instance accessor macro: <c>rbInstance</c>.</summary>
    internal const string INSTANCE_ACCESSOR = "rbInstance";

    /// <summary>The fragment-stage instance-index input: <c>rbInstanceIndex</c>.</summary>
    internal const string INSTANCE_INDEX = "rbInstanceIndex";

    /// <summary>The vertex-stage instance-index output: <c>rbInstanceIndexOut</c>.</summary>
    internal const string INSTANCE_INDEX_OUT = "rbInstanceIndexOut";

    /// <summary>The user vertex function after macro renaming: <c>rbUserVertexMain</c>.</summary>
    internal const string USER_VERTEX_MAIN = "rbUserVertexMain";

    /// <summary>The user fragment function after macro renaming: <c>rbUserFragmentMain</c>.</summary>
    internal const string USER_FRAGMENT_MAIN = "rbUserFragmentMain";

    /// <summary>The GLSL vertex entry point: <c>main_vertex</c>.</summary>
    internal const string VERTEX_ENTRY_POINT = "main_vertex";

    /// <summary>The GLSL fragment entry point: <c>main_fragment</c>.</summary>
    internal const string FRAGMENT_ENTRY_POINT = "main_fragment";

    /// <summary>The generated wrapper function shaderc compiles: <c>main</c>.</summary>
    internal const string GLSL_ENTRY_POINT = "main";

    /// <summary>The suffix appended to a texture name to form its instance index field.</summary>
    internal const string TEXTURE_INDEX_FIELD_SUFFIX = "Index";

    /// <summary>The vertex varying location reserved for the engine instance index.</summary>
    internal const int RESERVED_VARYING_LOCATION = 15;
}
